export const stableDiffusionCppBrowser__gpu_budget_help = (): string => "Leer lassen, um ohne verwaltetes Budget die Zuweisungsgrenzen des Geräts zu verwenden. Ein optionales Budget umfasst gehaltene Gewichte und Arbeitspuffer, nicht die Modelldateigröße. Ein zu kleiner Wert kann die Generierung verhindern oder Transfers erhöhen; ein größerer Wert garantiert keinen freien Speicher. Explizite Wasm32-Budgets müssen unter 4096 MiB liegen.";
